#!/usr/bin/env node

/*
 * End-to-end ingestion soak for the production EventPoller. RPC responses are
 * generated by a bounded fake client; EventLog, IndexerStatus and mutation
 * records are written to a real, isolated MongoDB database.
 *
 * Run after `pnpm run build` with INDEXER_SOAK_MONGODB_URI set:
 *   node load-tests/indexer-ingestion.js                 # 50,000 events
 *   node load-tests/indexer-ingestion.js --events 5000    # CI-sized run
 */

const path = require('node:path');
const { performance } = require('node:perf_hooks');
const mongoose = require('mongoose');
const { xdr } = require('@stellar/stellar-sdk');
const dotenv = require('dotenv');

dotenv.config({ path: path.resolve(__dirname, '.env') });
dotenv.config({ path: path.resolve(__dirname, '../.env') });

process.env.NODE_ENV = process.env.NODE_ENV || 'test';
process.env.JWT_SECRET = process.env.JWT_SECRET || 'indexer-soak-test-secret';

const EventLog = require('../dist/src/models/EventLog').default;
const { IndexerStatus } = require('../dist/src/models/IndexerStatus');
const { EventPoller } = require('../dist/src/services/eventPoller');

const parsePositiveInteger = (name, value, fallback) => {
  const parsed = Number(value ?? fallback);
  if (!Number.isSafeInteger(parsed) || parsed < 1) {
    throw new Error(`${name} must be a positive safe integer`);
  }
  return parsed;
};

const option = (name, fallback) => {
  const index = process.argv.indexOf(name);
  return index < 0 ? fallback : process.argv[index + 1];
};

const eventCount = parsePositiveInteger(
  'INDEXER_SOAK_EVENT_COUNT',
  option('--events', process.env.INDEXER_SOAK_EVENT_COUNT),
  50_000,
);
if (eventCount > 250_000) throw new Error('event count cannot exceed 250,000');

const pageSize = parsePositiveInteger(
  'INDEXER_SOAK_PAGE_SIZE',
  option('--page-size', process.env.INDEXER_SOAK_PAGE_SIZE),
  500,
);
const eventsPerLedger = parsePositiveInteger(
  'INDEXER_SOAK_EVENTS_PER_LEDGER',
  option('--events-per-ledger', process.env.INDEXER_SOAK_EVENTS_PER_LEDGER),
  100,
);
const maximumLagLedgers = parsePositiveInteger(
  'INDEXER_SOAK_MAX_LAG_LEDGERS',
  option('--max-lag-ledgers', process.env.INDEXER_SOAK_MAX_LAG_LEDGERS),
  1_000,
);
const minimumEventsPerSecond = Number(
  option('--min-events-per-second', process.env.INDEXER_SOAK_MIN_EVENTS_PER_SECOND ?? 25),
);
const maximumP95LatencyMs = Number(
  option('--max-p95-ms', process.env.INDEXER_SOAK_MAX_P95_MS ?? 1_000),
);
const maximumHeapGrowthMb = Number(
  option('--max-heap-growth-mb', process.env.INDEXER_SOAK_MAX_HEAP_GROWTH_MB ?? 512),
);

for (const [name, value] of [
  ['INDEXER_SOAK_MIN_EVENTS_PER_SECOND', minimumEventsPerSecond],
  ['INDEXER_SOAK_MAX_P95_MS', maximumP95LatencyMs],
  ['INDEXER_SOAK_MAX_HEAP_GROWTH_MB', maximumHeapGrowthMb],
]) {
  if (!Number.isFinite(value) || value <= 0) throw new Error(`${name} must be positive`);
}

const mongoUri = process.env.INDEXER_SOAK_MONGODB_URI;
if (!mongoUri) {
  throw new Error(
    'Set INDEXER_SOAK_MONGODB_URI to a MongoDB instance intended for load testing. ' +
      'The harness creates and drops a uniquely named database.',
  );
}
const configuredDatabaseName = decodeURIComponent(new URL(mongoUri).pathname.slice(1));
if (!configuredDatabaseName.toLowerCase().includes('soak')) {
  throw new Error('The database name in INDEXER_SOAK_MONGODB_URI must contain "soak".');
}

const network = `indexer-soak-${process.pid}-${Date.now()}`;
const contractId = 'CSOAKFIXTURECONTRACT';
const eventTopic = 'indexer_soak';
const startLedger = 100_000;
const ledgerCount = Math.ceil(eventCount / eventsPerLedger);
const latestLedger = startLedger + ledgerCount - 1;
const topic = xdr.ScVal.scvSymbol(eventTopic);
const mutationSchema = new mongoose.Schema(
  {
    transactionHash: { type: String, required: true, unique: true },
    mutationCount: { type: Number, required: true, default: 0 },
  },
  { versionKey: false },
);
const SoakMutation = mongoose.model('IndexerSoakMutation', mutationSchema);

const makeEvent = (index) => {
  const ledger = startLedger + Math.floor(index / eventsPerLedger);
  return {
    id: `soak-event-${index}`,
    type: 'contract',
    ledger,
    ledgerClosedAt: new Date(ledger * 1_000).toISOString(),
    contractId,
    txHash: `soak-tx-${index}`,
    topic: [topic],
    value: xdr.ScVal.scvVoid(),
    inSuccessfulContractCall: true,
    pagingToken: `soak-event-${index}`,
  };
};

const run = async () => {
  const databaseName = `swiftchain_indexer_soak_${process.pid}_${Date.now()}`;
  await mongoose.connect(mongoUri, { dbName: databaseName });
  await Promise.all([EventLog.init(), IndexerStatus.init(), SoakMutation.init()]);

  await IndexerStatus.create({
    network,
    lastProcessedLedger: startLedger - 1,
    lastProcessedAt: new Date(),
  });

  let offset = 0;
  let maximumLag = 0;
  let maximumHeapBytes = process.memoryUsage().heapUsed;
  const initialHeapBytes = maximumHeapBytes;
  const handlerLatenciesMs = [];

  const rpc = {
    getLatestLedger: async () => ({ sequence: latestLedger }),
    getEvents: async (request) => {
      const cursor = request.cursor === undefined ? undefined : Number(request.cursor);
      if (cursor !== undefined) offset = cursor;
      else {
        offset = Math.max(0, (request.startLedger ?? startLedger) - startLedger) * eventsPerLedger;
      }

      const end = Math.min(eventCount, offset + (request.limit ?? pageSize));
      const events = Array.from({ length: end - offset }, (_, index) => makeEvent(offset + index));
      const deliveredAt = performance.now();
      for (const event of events) event.soakDeliveredAt = deliveredAt;
      offset = end;

      const checkpoint = await IndexerStatus.findOne({ network }).lean();
      maximumLag = Math.max(maximumLag, latestLedger - (checkpoint?.lastProcessedLedger ?? 0));
      maximumHeapBytes = Math.max(maximumHeapBytes, process.memoryUsage().heapUsed);

      return {
        latestLedger,
        events,
        cursor: String(offset),
      };
    },
  };

  const poller = new EventPoller({
    rpc,
    network,
    contractId,
    subscriptions: [
      {
        eventType: 'escrow',
        topic: eventTopic,
        handle: async (event) => {
          const deliveredAt = event.soakDeliveredAt;
          if (typeof deliveredAt !== 'number') throw new Error('fake RPC delivery timestamp missing');
          handlerLatenciesMs.push(performance.now() - deliveredAt);
          await SoakMutation.updateOne(
            { transactionHash: event.txHash },
            { $inc: { mutationCount: 1 } },
            { upsert: true },
          );
          maximumHeapBytes = Math.max(maximumHeapBytes, process.memoryUsage().heapUsed);
        },
      },
    ],
    intervalMs: 60_000,
    pageSize,
  });

  const startedAt = performance.now();
  const result = await poller.pollOnce();
  const durationSeconds = (performance.now() - startedAt) / 1_000;
  const eventsPerSecond = result.processed / durationSeconds;
  handlerLatenciesMs.sort((left, right) => left - right);
  const p95LatencyMs = handlerLatenciesMs[Math.ceil(handlerLatenciesMs.length * 0.95) - 1];
  const heapGrowthMb = (maximumHeapBytes - initialHeapBytes) / (1024 * 1024);
  const checkpoint = await IndexerStatus.findOne({ network }).lean();
  const mutationCount = await SoakMutation.countDocuments({});
  const duplicateMutationCount = await SoakMutation.countDocuments({ mutationCount: { $ne: 1 } });
  await IndexerStatus.updateOne(
    { network },
    { $set: { lastProcessedLedger: startLedger - 1, lastProcessedAt: new Date() } },
  );
  const duplicatePass = await poller.pollOnce();
  const postReplayMutationCount = await SoakMutation.countDocuments({});
  const postReplayDuplicateMutationCount = await SoakMutation.countDocuments({ mutationCount: { $ne: 1 } });

  const metrics = {
    events: eventCount,
    ledgers: ledgerCount,
    pages: Math.ceil(eventCount / pageSize),
    duration_seconds: Number(durationSeconds.toFixed(3)),
    events_per_second: Number(eventsPerSecond.toFixed(2)),
    p95_ingest_latency_ms: Number(p95LatencyMs.toFixed(2)),
    heap_growth_mb: Number(heapGrowthMb.toFixed(2)),
    high_water_lag_ledgers: maximumLag,
    final_lag_ledgers: latestLedger - (checkpoint?.lastProcessedLedger ?? 0),
    event_log_entries: await EventLog.countDocuments({ eventType: 'escrow' }),
    mutation_entries: mutationCount,
    duplicate_mutations: duplicateMutationCount,
    post_replay_mutation_entries: postReplayMutationCount,
    post_replay_duplicate_mutations: postReplayDuplicateMutationCount,
    duplicate_replay_events: duplicatePass.duplicates,
    checkpoint_ledger: checkpoint?.lastProcessedLedger ?? null,
  };

  const failures = [];
  if (result.fetched !== eventCount || result.processed !== eventCount || result.failed !== 0) {
    failures.push('not all generated events were processed successfully');
  }
  if (eventsPerSecond < minimumEventsPerSecond) failures.push('throughput fell below its configured minimum');
  if (p95LatencyMs > maximumP95LatencyMs) failures.push('p95 ingest latency exceeded its configured maximum');
  if (heapGrowthMb > maximumHeapGrowthMb) failures.push('heap growth exceeded its configured maximum');
  if (maximumLag > maximumLagLedgers) failures.push('high-water checkpoint lag exceeded its configured maximum');
  if (metrics.final_lag_ledgers !== 0 || checkpoint?.lastProcessedLedger !== latestLedger) {
    failures.push('checkpoint did not converge to the latest ledger');
  }
  if (metrics.event_log_entries !== eventCount || metrics.mutation_entries !== eventCount) {
    failures.push('database record counts did not match generated events');
  }
  if (duplicateMutationCount !== 0) failures.push('at least one event mutated state more than once');
  if (postReplayMutationCount !== eventCount || postReplayDuplicateMutationCount !== 0) {
    failures.push('duplicate replay changed handler mutation state');
  }
  if (
    duplicatePass.fetched !== eventCount ||
    duplicatePass.processed !== 0 ||
    duplicatePass.duplicates !== eventCount
  ) {
    failures.push('duplicate replay was not suppressed by the EventLog idempotency key');
  }

  process.stdout.write(`${JSON.stringify({ status: failures.length === 0 ? 'PASS' : 'FAIL', metrics, failures }, null, 2)}\n`);
  if (failures.length > 0) process.exitCode = 1;
};

run()
  .catch((error) => {
    process.stderr.write(`${error instanceof Error ? error.stack : String(error)}\n`);
    process.exitCode = 1;
  })
  .finally(async () => {
    if (mongoose.connection.readyState !== 0) {
      await mongoose.connection.dropDatabase().catch(() => undefined);
      await mongoose.disconnect();
    }
  });
